         return -1;
      if (aimee_db2_memory_row_take(payload, payload_len, &cursor, rows[index].action_text,
                                    AIMEE_DB2_PROSPECTIVE_LIST_ARMED_ACTION_TEXT_MAX) != 0)
         return -1;
