typedef struct
{
   char node[AIMEE_DB2_ENTITY_NEIGHBORS_WEIGHTED_NODE_MAX + 1];
   uint32_t weight;
   double utility_score;
   double effective_utility;
} aimee_db2_entity_neighbors_weighted_row_t;

static inline int aimee_db2_entity_neighbors_weighted_reply_encode(const aimee_db2_entity_neighbors_weighted_row_t *rows,
                                                 uint32_t count, uint8_t *output, size_t capacity,
                                                 uint32_t *output_len)
{
   if (output_len)
      *output_len = 0u;
   if (!output || !output_len || (count > 0u && !rows) || count > AIMEE_DB2_ENTITY_NEIGHBORS_WEIGHTED_MAX_ROWS)
      return -1;
   uint8_t scratch[AIMEE_DB2_ENTITY_NEIGHBORS_WEIGHTED_RESPONSE_MAX_LEN - AIMEE_DB2_ENVELOPE_HEADER_LEN];
   uint8_t *payload = scratch;
   aimee_db2_put_u32(payload, count);
   uint32_t cursor = 4u;
   for (uint32_t index = 0u; index < count; index++)
   {
      size_t node_len = 0u;
      while (node_len <= AIMEE_DB2_ENTITY_NEIGHBORS_WEIGHTED_NODE_MAX && rows[index].node[node_len])
         ++node_len;
      if (node_len > AIMEE_DB2_ENTITY_NEIGHBORS_WEIGHTED_NODE_MAX ||
       rows[index].weight > AIMEE_DB2_ENTITY_NEIGHBORS_WEIGHTED_WEIGHT_MAX ||
       (aimee_db2_binary64_bits(rows[index].utility_score) & 0x7fffffffffffffffull) > AIMEE_DB2_ENTITY_NEIGHBORS_WEIGHTED_UTILITY_SCORE_MAX_MAGNITUDE_BITS ||
       (aimee_db2_binary64_bits(rows[index].effective_utility) & 0x7fffffffffffffffull) > AIMEE_DB2_ENTITY_NEIGHBORS_WEIGHTED_EFFECTIVE_UTILITY_MAX_MAGNITUDE_BITS)
         return -1;
      aimee_db2_put_u32(payload + cursor, (uint32_t)node_len);
      memcpy(payload + cursor + 4u, rows[index].node, node_len);
      cursor += 4u + (uint32_t)node_len;
      aimee_db2_put_u32(payload + cursor, rows[index].weight);
      cursor += 4u;
      aimee_db2_put_u64(payload + cursor, aimee_db2_binary64_bits(rows[index].utility_score));
      cursor += 8u;
      aimee_db2_put_u64(payload + cursor, aimee_db2_binary64_bits(rows[index].effective_utility));
      cursor += 8u;
   }
   if (capacity < (size_t)AIMEE_DB2_ENVELOPE_HEADER_LEN + cursor ||
       aimee_db2_reply_header_encode(AIMEE_DB2_OPERATION_ENTITY_NEIGHBORS_WEIGHTED, AIMEE_DB2_RESULT_OK, cursor,
                                     output, capacity) != 0)
      return -1;
   memcpy(output + AIMEE_DB2_ENVELOPE_HEADER_LEN, scratch, cursor);
   *output_len = AIMEE_DB2_ENVELOPE_HEADER_LEN + cursor;
   return 0;
}

static inline int aimee_db2_entity_neighbors_weighted_reply_decode(const uint8_t *input, size_t input_len,
                                                 aimee_db2_entity_neighbors_weighted_row_t *rows, uint32_t capacity,
                                                 uint32_t *count)
{
   if (count)
      *count = 0u;
   if (!count || (capacity > 0u && !rows))
      return -1;
   aimee_db2_reply_header_t header = {0};
   if (aimee_db2_reply_header_decode(input, input_len, &header) != 0 ||
       header.operation != AIMEE_DB2_OPERATION_ENTITY_NEIGHBORS_WEIGHTED ||
       header.result != AIMEE_DB2_RESULT_OK || header.payload_len < 4u ||
       input_len != (size_t)AIMEE_DB2_ENVELOPE_HEADER_LEN + header.payload_len)
      return -1;
   const uint8_t *payload = input + AIMEE_DB2_ENVELOPE_HEADER_LEN;
   uint32_t payload_len = header.payload_len;
   uint32_t decoded = aimee_db2_get_u32(payload);
   if (decoded > AIMEE_DB2_ENTITY_NEIGHBORS_WEIGHTED_MAX_ROWS || decoded > capacity)
      return -1;
   uint32_t cursor = 4u;
   for (uint32_t index = 0u; index < decoded; index++)
   {
      memset(&rows[index], 0, sizeof(rows[index]));
      if (aimee_db2_memory_row_take(payload, payload_len, &cursor, rows[index].node,
                                    AIMEE_DB2_ENTITY_NEIGHBORS_WEIGHTED_NODE_MAX) != 0)
         return -1;
      if (cursor + 4u > payload_len)
         return -1;
      rows[index].weight = aimee_db2_get_u32(payload + cursor);
      cursor += 4u;
      if (rows[index].weight > AIMEE_DB2_ENTITY_NEIGHBORS_WEIGHTED_WEIGHT_MAX)
         return -1;
      if (cursor + 8u > payload_len)
         return -1;
      {
         uint64_t bits = aimee_db2_get_u64(payload + cursor);
         cursor += 8u;
         if ((bits & 0x7fffffffffffffffull) > AIMEE_DB2_ENTITY_NEIGHBORS_WEIGHTED_UTILITY_SCORE_MAX_MAGNITUDE_BITS)
            return -1;
         rows[index].utility_score = aimee_db2_binary64_value(bits);
      }
      if (cursor + 8u > payload_len)
         return -1;
      {
         uint64_t bits = aimee_db2_get_u64(payload + cursor);
         cursor += 8u;
         if ((bits & 0x7fffffffffffffffull) > AIMEE_DB2_ENTITY_NEIGHBORS_WEIGHTED_EFFECTIVE_UTILITY_MAX_MAGNITUDE_BITS)
            return -1;
         rows[index].effective_utility = aimee_db2_binary64_value(bits);
      }
   }
   if (cursor != payload_len)
      return -1;
   *count = decoded;
   return 0;
}

